-- Additional business metadata and scoped AI policy. No legacy data is seeded.
CREATE TABLE IF NOT EXISTS bf_profiles(business_id TEXT PRIMARY KEY REFERENCES portfolio_businesses(id),overview TEXT NOT NULL,category TEXT NOT NULL,started_on TEXT,enabled INTEGER NOT NULL DEFAULT 1,ai_enforced INTEGER NOT NULL DEFAULT 0,revision INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS bf_creations(request_key TEXT PRIMARY KEY,business_id TEXT UNIQUE NOT NULL REFERENCES bf_profiles(business_id),fingerprint TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS bf_ai_assignments(business_id TEXT NOT NULL REFERENCES bf_profiles(business_id),agent TEXT NOT NULL,role_note TEXT NOT NULL,scope_note TEXT NOT NULL,permissions TEXT NOT NULL,active INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,PRIMARY KEY(business_id,agent));
CREATE TABLE IF NOT EXISTS bf_kpis(business_id TEXT NOT NULL REFERENCES bf_profiles(business_id),metric_key TEXT NOT NULL,label TEXT NOT NULL,unit TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,revision INTEGER NOT NULL DEFAULT 1,PRIMARY KEY(business_id,metric_key));
CREATE TABLE IF NOT EXISTS bf_kpi_samples(business_id TEXT NOT NULL,metric_key TEXT NOT NULL,day TEXT NOT NULL,mode TEXT NOT NULL,value TEXT NOT NULL,evidence TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1,PRIMARY KEY(business_id,metric_key,day,mode),FOREIGN KEY(business_id,metric_key) REFERENCES bf_kpis(business_id,metric_key));
CREATE TABLE IF NOT EXISTS bf_events(id INTEGER PRIMARY KEY,business_id TEXT NOT NULL REFERENCES portfolio_businesses(id),actor TEXT NOT NULL,event TEXT NOT NULL,ref TEXT NOT NULL,detail TEXT NOT NULL,created_at TEXT NOT NULL);
